    result->scheme = uri;
    result->scheme_len = p - uri;

    /* check if authority part exists '://' */
    if (((uri_end - p) > 2) && (p[1] == '/') && (p[2] == '/')) {
        *has_authority = true;
        /* skip '://' */
        return p + 3;
    }

    /* skip ':' */
