static int ufshcd_exec_dev_cmd(struct ufs_hba *hba,
		enum dev_cmd_type cmd_type, int timeout)
{
	struct request_queue *q = hba->cmd_queue;
	DECLARE_COMPLETION_ONSTACK(wait);
	struct request *req;
	struct ufshcd_lrb *lrbp;
	int err;
	int tag;

